window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-2f7a433b75ec5268"]={"versions": [{"id": "FIG-2f7a433b75ec5268", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Strukturelles Bit- und Byte-Layout-Diagramm (Protokoll-/Speicherformat) zur Spezifikation des Datenformats eines Debug-Datenrekords (Data Record structure) im Rahmen des AUTOSAR-Debugging-Moduls (AUTOSAR_SWS_Debugging). Das Diagramm visualisiert die segmentierte Datenfeldanordnung einschließlich Header-Feldern, Bitmasken, Zeitstempel und Nutzdatenbereich zur Erfüllung von SRS_Dbg_00020.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Datensatzformat gliedert sich in folgende aufeinanderfolgende Entitäten und Bit-/Bytefelder:</p>\n<ul class=\"fig-list\"><li>Header-Bereich (16 Bit):\n<ul class=\"fig-list\"><li><strong>DID</strong> (Bits 0–7): Data Identifier bzw. Identifikator des Datensatzes (8 Bit).\n</li><li><strong>Data Control Bits</strong> (Bits 8–10): Steuerbits zur Qualifizierung der Datenerfassung/Interpretation (3 Bit).\n</li><li><strong>Buffer Overflow Bit</strong> (Bit 11): Statusbit zur Signalisierung eines Pufferüberlaufs im Erfassungskontext (1 Bit).\n</li><li><strong>Reserved¹</strong> (Bits 12–15): Für zukünftige Zwecke reservierte Steuerbits mit Fußnotenverweis 1 (4 Bit).\n</li></ul>\n</li><li>Optionales Zeitstempelfeld:\n<ul class=\"fig-list\"><li><strong>Time stamp (optional, 16 or 32 bits)</strong>: Optionales Timestamp-Feld mit variabler konfigurierter Breite (16 oder 32 Bit).\n</li></ul>\n</li><li>Nutzdatenfeld:\n<ul class=\"fig-list\"><li><strong>Data</strong>: Variabler Nutzdatenbereich mit den eigentlichen zu protokollierenden Debug-Messwerten/Signaldaten.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Felddefinition eines sequentiell serialisierten Datensatzes:</p>\n<ol class=\"fig-list\"><li>Der Datensatz beginnt zwingend mit dem 16-Bit-Steuerheader (Bits 0 bis 15), zusammengesetzt aus DID (Bits 0..7), Control Bits (Bits 8..10), Overflow-Flag (Bit 11) und reservierten Bits (Bits 12..15).\n</li><li>Abhängig von der Konfiguration folgt unmittelbar nach dem 16-Bit-Header ein Zeitstempel fester Wortbreite (16 oder 32 Bit) oder dieser entfällt.\n</li><li>Den Abschluss bildet der zusammenhängende Payload-Block (<code>Data</code>), der die durch den DID referenzierten Messdaten aufnimmt.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Vorgabe gemäß SRS_Dbg_00020 für Serialisierung, Parsing und Pufferung von Debug-Daten durch das Debug-Modul:</p>\n<ul class=\"fig-list\"><li>Implementierungen müssen die exakten Bitpositionen 0–7 (DID), 8–10 (Data Control Bits), 11 (Buffer Overflow) und 12–15 (Reserved) im ersten 16-Bit-Wort einhalten.\n</li><li>Das Vorhandensein und die Bitbreite des Felds <code>Time stamp</code> (0, 16 oder 32 Bit) müssen zur Compile- oder Konfigurationszeit statisch bzw. pro Datenstrom festgelegt werden, um ein deterministisches Dekodieren des nachfolgenden Felds <code>Data</code> zu gewährleisten.\n</li><li>Reservierte Bits (12–15) sind standardmäßig gemäß Modulvorgaben auf 0 zu setzen und vom Empfänger zu ignorieren.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-c88350ea4b8a88b3", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Strukturelles Bit- und Byte-Layout-Diagramm (Protokoll-/Speicherformat) zur Spezifikation des Datenformats eines Debug-Datenrekords (Data Record structure) im Rahmen des AUTOSAR-Debugging-Moduls (AUTOSAR_SWS_Debugging). Das Diagramm visualisiert die segmentierte Datenfeldanordnung einschließlich Header-Feldern, Bitmasken, Zeitstempel und Nutzdatenbereich zur Erfüllung von SRS_Dbg_00020.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Datensatzformat gliedert sich in folgende aufeinanderfolgende Entitäten und Bit-/Bytefelder:</p>\n<ul class=\"fig-list\"><li>Header-Bereich (16 Bit):\n<ul class=\"fig-list\"><li><strong>DID</strong> (Bits 0–7): Data Identifier bzw. Identifikator des Datensatzes (8 Bit).\n</li><li><strong>Data Control Bits</strong> (Bits 8–10): Steuerbits zur Qualifizierung der Datenerfassung/Interpretation (3 Bit).\n</li><li><strong>Buffer Overflow Bit</strong> (Bit 11): Statusbit zur Signalisierung eines Pufferüberlaufs im Erfassungskontext (1 Bit).\n</li><li><strong>Reserved¹</strong> (Bits 12–15): Für zukünftige Zwecke reservierte Steuerbits mit Fußnotenverweis 1 (4 Bit).\n</li></ul>\n</li><li>Optionales Zeitstempelfeld:\n<ul class=\"fig-list\"><li><strong>Time stamp (optional, 16 or 32 bits)</strong>: Optionales Timestamp-Feld mit variabler konfigurierter Breite (16 oder 32 Bit).\n</li></ul>\n</li><li>Nutzdatenfeld:\n<ul class=\"fig-list\"><li><strong>Data</strong>: Variabler Nutzdatenbereich mit den eigentlichen zu protokollierenden Debug-Messwerten/Signaldaten.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Felddefinition eines sequentiell serialisierten Datensatzes:</p>\n<ol class=\"fig-list\"><li>Der Datensatz beginnt zwingend mit dem 16-Bit-Steuerheader (Bits 0 bis 15), zusammengesetzt aus DID (Bits 0..7), Control Bits (Bits 8..10), Overflow-Flag (Bit 11) und reservierten Bits (Bits 12..15).\n</li><li>Abhängig von der Konfiguration folgt unmittelbar nach dem 16-Bit-Header ein Zeitstempel fester Wortbreite (16 oder 32 Bit) oder dieser entfällt.\n</li><li>Den Abschluss bildet der zusammenhängende Payload-Block (<code>Data</code>), der die durch den DID referenzierten Messdaten aufnimmt.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Vorgabe gemäß SRS_Dbg_00020 für Serialisierung, Parsing und Pufferung von Debug-Daten durch das Debug-Modul:</p>\n<ul class=\"fig-list\"><li>Implementierungen müssen die exakten Bitpositionen 0–7 (DID), 8–10 (Data Control Bits), 11 (Buffer Overflow) und 12–15 (Reserved) im ersten 16-Bit-Wort einhalten.\n</li><li>Das Vorhandensein und die Bitbreite des Felds <code>Time stamp</code> (0, 16 oder 32 Bit) müssen zur Compile- oder Konfigurationszeit statisch bzw. pro Datenstrom festgelegt werden, um ein deterministisches Dekodieren des nachfolgenden Felds <code>Data</code> zu gewährleisten.\n</li><li>Reservierte Bits (12–15) sind standardmäßig gemäß Modulvorgaben auf 0 zu setzen und vom Empfänger zu ignorieren.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-2f7a433b75ec5268", "to": "FIG-c88350ea4b8a88b3", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
